spec.expr:
sum by (pod) (
  rate(container_cpu_usage_seconds_total{
    namespace="devsecops",
    container!="",
    container!="POD"
  }[5m])
)

sum by (pod) (
  container_memory_working_set_bytes{
    namespace="devsecops",
    container!="",
    container!="POD"
  }
)

100 *
(
  sum by (job) (
    rate(http_server_requests_seconds_count{
      namespace="devsecops",
      status=~"4.."
    }[5m])
  )
  or
  (
    sum by (job) (
      rate(http_server_requests_seconds_count{
        namespace="devsecops"
      }[5m])
    ) * 0
  )
)
/
sum by (job) (
  rate(http_server_requests_seconds_count{
    namespace="devsecops"
  }[5m])
)

histogram_quantile(
  0.95,
  sum by (job, le) (
    rate(
      http_server_requests_seconds_bucket{
        namespace="devsecops"
      }[5m]
    )
  )
)

count(
  kube_pod_status_ready{
    namespace="devsecops",
    condition="true"
  } == 0
)
or
vector(0)

count(
  kube_pod_status_phase{
    namespace="devsecops",
    phase="Pending"
  } == 1
) or vector(0)

100 *
(
  sum by (job) (
    rate(http_server_requests_seconds_count{
      namespace="devsecops",
      status=~"5.."
    }[5m])
  )
  or
  (
    sum by (job) (
      rate(http_server_requests_seconds_count{
        namespace="devsecops"
      }[5m])
    ) * 0
  )
)
/
sum by (job) (
  rate(http_server_requests_seconds_count{
    namespace="devsecops"
  }[5m])
)

100 *
sum by (job) (
  jvm_memory_used_bytes{
    namespace="devsecops",
    area="heap"
  }
)
/
sum by (job) (
  jvm_memory_max_bytes{
    namespace="devsecops",
    area="heap"
  }
)
